draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // conflicting beliefs
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2);
  ctx.lineTo(W/2 - 30 + 20*Math.sin(t), H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2);
  ctx.lineTo(W/2 + 30 + 20*Math.cos(t), H/2 + 20);
  ctx.stroke();

  // action
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 30 + 20*Math.sin(2*t));
  ctx.stroke();

  ctx.restore();
}
